{
    size_t i;
    double margin;
    adcs_vec3_t axis;
    adcs_status_t st;

    if ((minimum_margin == NULL) || (limiting_index == NULL) || (momentum == NULL) ||
        (reserve_vector == NULL))
        return ADCS_E_NULL;

    *minimum_margin = INFINITY;
    *limiting_index = SIZE_MAX;
    *momentum = (adcs_vec3_t){0, 0, 0};
    *reserve_vector = (adcs_vec3_t){0, 0, 0};

    if ((wheels == NULL) || (speed_limits == NULL))
        return ADCS_E_NULL;
    if ((count < 1U) || (count > 16U))
        return ADCS_E_RANGE;

    for (i = 0; i < count; i++) {
        if ((!isfinite(speed_limits[i])) || (speed_limits[i] <= 0.0))
            return ADCS_E_RANGE;
        if ((!isfinite(wheels[i].inertia_kg_m2)) || (wheels[i].inertia_kg_m2 <= 0.0))
            return ADCS_E_RANGE;
        if (!isfinite(wheels[i].speed_rad_s))
            return ADCS_E_RANGE;
        if (!adcs_is_finite_vec3(&wheels[i].axis_body))
            return ADCS_E_RANGE;
        if (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis) != ADCS_OK)
            return ADCS_E_RANGE;

        margin = speed_limits[i] - fabs(wheels[i].speed_rad_s);
        if (margin < *minimum_margin) {
            *minimum_margin = margin;
            *limiting_index = i;
        }
        {
            adcs_vec3_t term = adcs_vec3_scale(&axis, wheels[i].inertia_kg_m2 * margin);
            *reserve_vector = adcs_vec3_add(reserve_vector, &term);
        }
    }

    st = adcs_wheel_momentum(wheels, count, momentum);
    return st;
}
}

